package service;import java.io.*;import java.nio.file.*;import java.util.*;import model.Account;public class StatePersister{public static void save(Collection<Account>a,Path p)throws IOException{try(ObjectOutputStream o=new ObjectOutputStream(Files.newOutputStream(p))){o.writeObject(new ArrayList<>(a));}}@SuppressWarnings("unchecked")public static List<Account> load(Path p)throws IOException,ClassNotFoundException{if(!Files.exists(p))return new ArrayList<>();try(ObjectInputStream i=new ObjectInputStream(Files.newInputStream(p))){return (List<Account>)i.readObject();}}}
